  Auditoria: ['id', 'ocorrido_em', 'evento', 'ator', 'telefone_hash', 'referencia', 'detalhe'],
};
function linha(aba, dados) {
  const out = {};
  for (const c of COLUNAS[aba]) out[c] = sanitizeCell(dados[c]);
  return out;
}
